from module_adapters._graph_extended_support import Diagram,validate
SOURCE='signed-gcn-modules/src/signedsageconvolution.py';KEY='signed_graphconv_base'
LINKS=[('edges','remove','edges','topology'),('remove','mean','edges','topology'),('x','mean','features','tensor'),('mean','concat','neighbors','tensor'),('x','concat','self','retained_value'),('concat','project','features','tensor'),('weight','project','W','parameter_operand'),('project','biasadd','features','tensor'),('bias','biasadd','bias','parameter_operand'),('biasadd','normalize','in','tensor'),('normalize','output','in','tensor')]
REQUIRED={'remove':dict(remove_self_loops=True,add_self_loops=False),'mean':dict(source_state='x',reduction='mean'),'concat':dict(ordered_operands=['neighbor_mean','x'],dim=1),'weight':dict(parameter='weight',shape='[16,4]'),'normalize':dict(p=2,dim=-1)}
CONTRACTS=[('SignedSAGEConvolutionBase.forward','remove_self_loops(edge_index, None)'),('SignedSAGEConvolutionBase.forward','scatter_mean(x[col], row, dim=0, dim_size=x.size(0))'),('SignedSAGEConvolutionBase.forward','torch.cat((out, x), 1)'),('SignedSAGEConvolutionBase.forward','F.normalize(out, p=2, dim=-1)')]
def build():
 d=Diagram(KEY,'Signed graph first-layer convolution',SOURCE,'SignedSAGEConvolutionBase.forward','One Base signed layer on one edge set, norm=True,norm_embed=True,bias=True; excludes paired task-network outputs.',dict(feature_dim=8,in_channels=16,out_channels=4,norm=True,norm_embed=True,bias=True,self_loops='remove only',add_self_loops=False))
 init=d.ref('SignedSAGEConvolution.__init__')
 d.input('x','Node features x','[N,8]');d.input('edges','Supplied single edge set','[2,E]',kind='control');d.input('weight','Owned weight W','[16,4]',kind='parameter',source=init,parameter='weight');d.input('bias','Owned bias b','[4]',kind='parameter',source=init,parameter='bias')
 d.node('remove','REMOVE self loops only','control','[2,E_without_self]',0,**REQUIRED['remove']);d.node('mean','Mean of neighbors without self','mean','[N,8]',1,**REQUIRED['mean'],opaque_scatter=True);d.node('concat','Concat NEIGHBOR then SELF','cat','[N,16]',2,**REQUIRED['concat']);d.node('project','Concatenated features @ W','matmul','[N,4]',3);d.node('biasadd','Add owned bias','add','[N,4]',4);d.node('normalize','L2 normalize each node','normalize','[N,4]',5,p=2,dim=-1)
 for s,t,p,r in LINKS:d.edge(s,t,p,r,ss='left' if r=='retained_value' else 'out',ds='left' if r=='retained_value' else 'in')
 return d.build(d.entry,'[N,4]','SignedGraphConvBase.md',['Base layer removes self loops, aggregates one feature state over one edge set, and concatenates neighbor mean then original x.','There is no add_self_loops call in Base forward. This is a real semantic difference from the Deep signed layer.','Owned weight[16,4], bias[4] and final L2 normalization are selected; outside caller may instantiate separate Base layers for different edge types.'],['Do not copy the Deep two-state/three-operand structure or add self loops absent from this module.'])
def validate_ir(ir):return validate(ir,KEY,REQUIRED,LINKS,dict(self_loops='remove only',add_self_loops=False))
